func quickSort(arr []int, start, end int) {
    if start < end {
        i, j := start, end
        key := arr[(start+end)/2]          // 取中间元素为 pivot
        for i <= j {
            for arr[i] < key {
                i++                         // 左指针右移找 ≥ key
            }
            for arr[j] > key {
                j--                         // 右指针左移找 ≤ key
            }
            if i <= j {
                arr[i], arr[j] = arr[j], arr[i]
                i++
                j--
            }
        }
        if start < j {
            quickSort(arr, start, j)        // 递归排序左半
        }
        if end > i {
            quickSort(arr, i, end)          // 递归排序右半
        }
    }
}

func insertionSort(a []int, n int) {
	// 对 a[1],a[2],...,a[n] 进行插入排序
	for i := 2; i <= n; i++ {
		key := a[i]
		j := i - 1
		for ; j > 0 && a[j] > key; {
			a[j+1] = a[j]
			j--
		}
		a[j+1] = key
	}
}

