type node struct {
	l, r, p *node
	v       int
	c       bool // false = red, true = black
}

type Tree struct {
	root *node
	last *node
	size int
}

func NewTree() *Tree { return &Tree{} }

// ===== 辅助：祖父 / 叔父 / 兄弟 =====

func (n *node) getGp() *node {
	if n.p == nil {
		return nil
	}
	if n.p.p == nil {
		return nil
	}
	return n.p.p
}

func (n *node) getUn() *node {
	if n.getGp() == nil {
		return nil
	}
	if n.p == n.getGp().l {
		return n.getGp().r
	}
	return n.getGp().l
}

func (n *node) br() *node {
	if n.p.l == n {
		return n.r
	}
	return n.l
}

// ===== 旋转 =====

func (tree *Tree) rotateR(n *node) {
	gp := n.getGp()
	p := n.p
	r := n.r

	n.r = p
	n.p = gp

	if p != nil {
		p.p = n
		p.l = r
		if r != nil {
			r.p = p
		}
	}
	if tree.root == p {
		tree.root = n
	}
	if gp != nil {
		if gp.l == p {
			gp.l = n
		} else {
			gp.r = n
		}
	}
}

func (tree *Tree) rotateL(n *node) {
	gp := n.getGp()
	p := n.p
	l := n.l

	n.l = p
	n.p = gp

	if p != nil {
		p.p = n
		p.r = l
		if l != nil {
			l.p = p
		}
	}
	if tree.root == p {
		tree.root = n
	}
	if gp != nil {
		if gp.l == p {
			gp.l = n
		} else {
			gp.r = n
		}
	}
}

// ===== 插入 =====

func (tree *Tree) insertB(v int) {
	if tree.root == nil {
		tree.root = &node{v: v, c: true}
		tree.size++
		return
	}

	if v < tree.root.v {
		if tree.Insert(&tree.root.l, v, tree.root) {
			tree.size++
			tree.inserCase(tree.last)
		}
	}
	if v > tree.root.v {
		if tree.Insert(&tree.root.r, v, tree.root) {
			tree.size++
			tree.inserCase(tree.last)
		}
	}
	printT(tree.root)
}

func (tree *Tree) Insert(n **node, v int, fa *node) bool {
	pn := *n
	if pn == nil {
		*n = &node{v: v, p: fa}
		tree.last = *n
		return true
	}
	if v > pn.v {
		return tree.Insert(&pn.r, v, pn)
	}
	if v < pn.v {
		return tree.Insert(&pn.l, v, pn)
	}
	return false // equal: not inserted
}

func (tree *Tree) inserCase(n *node) {
	if n.p == nil { // 根节点染黑
		n.c = true
		tree.root = n
		return
	}
	if n.p.c == false { // 父为红才需要修复
		if n.getUn() != nil && n.getUn().c == false {
			// 叔为红：父叔染黑，祖父染红，向上递归
			n.p.c = true
			n.getUn().c = true
			n.getGp().c = false
			tree.inserCase(n.getGp())
			return
		}
		// 叔为黑或 NIL：通过旋转 + 染色修复
		if n == n.p.r && n.p == n.getGp().l {
			tree.rotateL(n)
			tree.rotateR(n)
			n.c = true
			n.l.c, n.r.c = false, false
		} else if n == n.p.l && n.p == n.getGp().r {
			tree.rotateR(n)
			tree.rotateL(n)
			n.c = true
			n.l.c, n.r.c = false, false
		} else if n == n.p.l && n.p == n.getGp().l {
			n.p.c = true
			n.getGp().c = false
			tree.rotateR(n.p)
		} else if n == n.p.r && n.p == n.getGp().r {
			n.p.c = true
			n.getGp().c = false
			tree.rotateL(n.p)
		}
	}
}

// ===== 删除 =====

func (tree *Tree) tdelete(n *node, v int) {
	if n == nil {
		return
	}
	if v < n.v {
		tree.tdelete(n.l, v)
		return
	}
	if v > n.v {
		tree.tdelete(n.r, v)
		return
	}
	// v == n.v
	if n.l != nil && n.r != nil {
		mn := tree.findMax(n.l) // 左子树最大节点作为替换
		n.v = mn.v
		if tree.deleteR(mn) {
			tree.size--
		}
		return
	}
	if tree.deleteR(n) {
		tree.size--
	}
}

func (tree *Tree) findMax(n *node) *node {
	for n.r != nil {
		n = n.r
	}
	return n
}

func (tree *Tree) deleteR(n *node) bool {
	red, black := false, true

	// case 1: 删除的是根（无父 + 无子）
	if n.l == nil && n.r == nil && n.p == nil {
		tree.root = nil
		return true
	}

	var child *node
	if n.l != nil {
		child = n.l
	} else {
		child = n.r
	}

	// case 2: 删除后 child 升为新根
	if n.p == nil {
		child.p = nil
		tree.root = child
		child.c = black
		return true
	}

	if n.p.l == n {
		n.p.l = child
	} else {
		n.p.r = child
	}
	if child != nil {
		child.p = n.p
	}

	// 删除黑色节点才需要修复（少了一个黑高）
	if n.c == black {
		if child != nil && child.c == red {
			child.c = black // case: 红孩子顶替黑色被删节点
		} else {
			tree.fix2(n) // n 作为「双重黑」位置继续修复
		}
	}
	_ = red
	return true
}

// n 作为「双重黑」位置（黑高不平衡）的修复
func (tree *Tree) fix2(n *node) {
	black := true

	// case 1: 已到根
	if n.p == nil {
		n.c = black
		return
	}

	// case 2: 兄弟为红（旋转后转为 case 4/5/6）
	if n.br().c == false && n.p.c == black {
		n.p.c = false
		n.br().c = black
		if n == n.p.l {
			tree.rotateL(n.br())
		} else {
			tree.rotateR(n.br())
		}
	}

	// case 3: 父黑 + 兄黑 + 兄子全黑（黑高上移）
	if n.p.c == black && n.br().c == black && n.br().l == nil && n.br().r == nil {
		n.br().c = false
		tree.fix2(n.p)
		return
	}

	// case 4: 父红 + 兄黑 + 兄子全黑
	if n.p.c == false && n.br().c == black && n.br().l == nil && n.br().r == nil {
		n.p.c = black
		n.br().c = false
		return
	}

	// case 5: 兄黑 + 「近侄」红（先转成 case 6）
	if n.br().c == black {
		if n.br().l != nil && n.br().r == nil && n == n.p.l {
			n.br().c = false
			n.br().l.c = black
			tree.rotateR(n.br().l)
		} else if n.br().r != nil && n.br().l == nil && n == n.p.r {
			n.br().c = false
			n.br().r.c = black
			tree.rotateL(n.br().r)
		}
	}

	// case 6: 兄黑 + 「远侄」红（一轮修复结束）
	if n.br().c == black && n.br().r != nil && n == n.p.l {
		n.br().c = n.p.c
		tree.rotateL(n.br())
		n.p.c = black
		n.getGp().r.c = black
		return
	}
	if n.br().c == black && n.br().l != nil && n == n.p.r {
		n.br().c = n.p.c
		tree.rotateR(n.br())
		n.p.c = black
		n.getGp().l.c = black
		return
	}
}

